// Projection, validation and sampling shared by both renderers. No generated hills or routes.
const EARTH=6378137;
export function mercator(lon,lat){return [EARTH*lon*Math.PI/180,EARTH*Math.asinh(Math.tan(lat*Math.PI/180))]}
export function validateTerrain(data,id){if(!data||data.version!==1||data.courseId!==id)throw new Error('Terrain identity mismatch');const g=data.grid;if(!g||!Number.isInteger(g.width)||!Number.isInteger(g.height)||g.width<2||g.height<2||g.width>513||g.height>513||g.elevations?.length!==g.width*g.height)throw new Error('Invalid terrain grid');const b=g.boundsMercator;if(!Array.isArray(b)||b.length!==4||!b.every(Number.isFinite)||b[2]<=b[0]||b[3]<=b[1])throw new Error('Invalid terrain bounds');if(!g.elevations.every(v=>Number.isFinite(v)&&v>=-12000&&v<=9000))throw new Error('Invalid elevation value');const points=data.road?.coordinatesMercator;if(!Array.isArray(points)||points.length<2||!points.every(p=>Array.isArray(p)&&p.length===2&&p.every(Number.isFinite)&&p[0]>=b[0]&&p[0]<=b[2]&&p[1]>=b[1]&&p[1]<=b[3]))throw new Error('Invalid road geometry');if(!Array.isArray(data.road.anchors)||data.road.anchors.length<2)throw new Error('Missing road anchors');return data}
export function elevationAt(data,mx,my){const g=data.grid,b=g.boundsMercator;const x=Math.max(0,Math.min(g.width-1,(mx-b[0])/(b[2]-b[0])*(g.width-1))),y=Math.max(0,Math.min(g.height-1,(b[3]-my)/(b[3]-b[1])*(g.height-1)));const ix=Math.min(g.width-2,Math.floor(x)),iy=Math.min(g.height-2,Math.floor(y)),fx=x-ix,fy=y-iy;const a=g.elevations[iy*g.width+ix],c=g.elevations[iy*g.width+ix+1],d=g.elevations[(iy+1)*g.width+ix],e=g.elevations[(iy+1)*g.width+ix+1];return (a*(1-fx)+c*fx)*(1-fy)+(d*(1-fx)+e*fx)*fy}
export function makeTerrainModel(data){validateTerrain(data,data.courseId);const b=data.grid.boundsMercator,cx=(b[0]+b[2])/2,cy=(b[1]+b[3])/2,w=b[2]-b[0],h=b[3]-b[1],cos=1/Math.cosh(cy/EARTH),horizontal=32/Math.max(w,h),metersToWorld=horizontal/cos,exaggeration=2,min=data.grid.elevations.reduce((a,b)=>Math.min(a,b),Infinity),max=data.grid.elevations.reduce((a,b)=>Math.max(a,b),-Infinity),baseline=Math.floor(Math.max(0,min)/100)*100;
const toWorld=(mx,my)=>[(mx-cx)*horizontal,(Math.max(0,elevationAt(data,mx,my))-baseline)*metersToWorld*exaggeration+.26,(cy-my)*horizontal];const heightAt=(x,z)=>toWorld(cx+x/horizontal,cy-z/horizontal)[1];
const width=w*horizontal,depth=h*horizontal;const road=data.road.coordinatesMercator.map(([x,y])=>{const p=toWorld(x,y);p[1]+=.045;return p});const lengths=[0];for(let i=1;i<road.length;i++)lengths.push(lengths[i-1]+Math.hypot(road[i][0]-road[i-1][0],road[i][2]-road[i-1][2]));const total=lengths.at(-1);
function roadPoint(t){const d=Math.max(0,Math.min(1,t))*total;let lo=0,hi=lengths.length-1;while(lo<hi){const m=(lo+hi)>>1;if(lengths[m]<d)lo=m+1;else hi=m}const j=Math.max(1,lo),a=road[j-1],b=road[j],span=lengths[j]-lengths[j-1],f=span?(d-lengths[j-1])/span:0;const x=a[0]+(b[0]-a[0])*f,z=a[2]+(b[2]-a[2])*f;return{x,y:heightAt(x,z)+.06,z,heading:Math.atan2(b[0]-a[0],b[2]-a[2])}}
const anchors=data.road.anchors.map(a=>{const q=mercator(...a.coordinate),p=toWorld(...q);return{label:a.label,point:[p[0],p[1]+.16,p[2]],elevation:Math.round(elevationAt(data,...q))}});
return{data,width,depth,heightAt,toWorld,road,roadPoint,anchors,baseline,min,max,exaggeration,metersToWorld,horizontal,center:[cx,cy],peak:(Math.max(0,max)-baseline)*metersToWorld*exaggeration+.26}}
export function makeLatestTerrainLoader(fetcher){const cache=new Map();let version=0;return{async select(id){const token=++version;if(!cache.has(id)){const p=Promise.resolve().then(()=>fetcher(id)).then(d=>validateTerrain(d,id));cache.set(id,p);p.catch(()=>{if(cache.get(id)===p)cache.delete(id)})}const data=await cache.get(id);return{data,current:token===version}},invalidate(){version++},size(){return cache.size}}}
